// Injury-risk, recovery, and nutrition guidance generated by Claude from
// a summary of the athlete's own last-30-activities stats. This is a
// wellness heuristic written by an LLM from training-load patterns —
// explicitly not medical advice, and the UI must keep that disclaimer
// visible next to anything rendered from it.

import Anthropic from "@anthropic-ai/sdk";

const MODEL = "claude-opus-5";

const TOOL_NAME = "submit_health_analysis";

const ANALYSIS_TOOL = {
  name: TOOL_NAME,
  description: "Submit the structured Biomechanical & Overtraining Shield analysis for this athlete.",
  input_schema: {
    type: "object",
    properties: {
      risk_level: { type: "string", enum: ["low", "moderate", "high"] },
      // Anthropic's strict tool-schema mode rejects `minimum`/`maximum` on
      // integer properties (400 invalid_request_error) — the range is
      // enforced by clamping the returned value below instead.
      risk_score: { type: "integer", description: "An integer from 0 (negligible risk) to 100 (very high near-term injury risk)" },
      risk_summary: { type: "string", description: "1-2 sentence plain-language summary of the injury-risk read" },
      risk_factors: { type: "array", items: { type: "string" }, description: "3-6 short bullet points, each one specific contributing factor drawn from the given stats — call out aerobic decoupling, cadence drift, or ACWR spikes by their actual numbers whenever the data provided flags them" },
      recovery_plan: { type: "array", items: { type: "string" }, description: "3-6 short, concrete recovery recommendations tailored to this athlete's actual recent training" },
      nutrition_plan: { type: "array", items: { type: "string" }, description: "3-6 short, concrete nutrition suggestions tailored to this athlete's training volume and intensity" },
      training_adjustment: {
        type: "array",
        items: { type: "string" },
        description: "0-4 short, concrete adjustments to the athlete's upcoming 1-2 weeks of training — only populate this when the biomechanical or workload data actually signals a problem (high decoupling, falling cadence, or an ACWR spike); return an empty array when nothing in the data warrants changing the plan",
      },
    },
    required: ["risk_level", "risk_score", "risk_summary", "risk_factors", "recovery_plan", "nutrition_plan", "training_adjustment"],
    additionalProperties: false,
  },
  strict: true,
};

const SYSTEM_PROMPT = `You are the analysis engine behind the "Predictive Biomechanical & Overtraining Shield" \
feature of a Strava analytics app called Splitline. You are given an aggregated statistical summary of one \
athlete's last 30 imported activities — never raw personal data beyond what's in the summary. That summary \
includes deterministic, code-computed physics signals your analysis must be grounded in, not guess at: \
aerobic decoupling (a Pw:HR/Pa:HR efficiency-ratio drop between the first and second half of sustained \
efforts — under 5% is well-matched aerobic fitness, 5-10% borderline, over 10% a notable drift), cadence \
drift (stride/pedal rate falling late in an effort, a form-breakdown proxy), and acute:chronic workload \
ratio or "ACWR" (recent load vs. the athlete's own recent baseline; above roughly 1.5 is a commonly-cited \
sudden-spike injury-risk range), each broken out across rolling 7/30/60/90-day windows of whatever has \
actually been imported. Weave these specific numbers into risk_factors when they're notable — don't just \
restate generic training-load advice when the data gives you something concrete to point at. Also use \
weekly volume changes, rest-day frequency, intensity distribution, sport mix, and age if provided. Do not \
invent data points that were not given to you. If age is not provided, say so is one of the factors and \
reason from training patterns alone. Keep every bullet point short (under 25 words) and concrete — \
reference the actual numbers you were given rather than generic advice. Only fill training_adjustment when \
the data actually signals a problem worth changing near-term training for (high decoupling, falling \
cadence, or an ACWR spike) — leave it empty otherwise rather than inventing filler advice. This is wellness \
guidance, not a medical diagnosis; do not claim otherwise.`;

const TRAINING_PLAN_TOOL_NAME = "submit_training_plan";

const TRAINING_PLAN_TOOL = {
  name: TRAINING_PLAN_TOOL_NAME,
  description: "Submit the structured progressive training plan for this athlete's upcoming event.",
  input_schema: {
    type: "object",
    properties: {
      overview: { type: "string", description: "3-5 sentence summary of the overall approach: how the weeks available, this athlete's current fitness, and their goal finish time (if given) shape the plan" },
      phases: {
        type: "array",
        description: "3-8 periodized training phases (e.g. Base, Build, Peak, Taper) whose week ranges together span the full time until the event — group weeks into phases rather than listing every single week",
        items: {
          type: "object",
          properties: {
            name: { type: "string", description: "Phase name, e.g. 'Base', 'Build', 'Peak', 'Taper'" },
            weeks: { type: "string", description: "The week range this phase covers, e.g. 'Weeks 1-4'" },
            focus: { type: "string", description: "1-2 sentences on what this phase is training for and why it comes at this point in the plan" },
            weekly_volume_guidance: { type: "string", description: "Concrete weekly volume/frequency guidance for this phase (distance or duration and session count), referencing this athlete's actual recent volume" },
            weekly_time_estimate: { type: "string", description: "Approximate total training time per week during this phase, e.g. '5-7 hours/week'" },
            // No minimum/maximum here — Anthropic's strict tool-schema mode
            // rejects those on integer properties; range is described in
            // text and the value is clamped in code after the call.
            relative_load: { type: "integer", description: "An integer from 0-100 expressing this phase's training load relative to the plan's peak week (100 = the single highest-load week of the whole plan) — used to draw a training-progress chart, so keep it consistent phase to phase (e.g. Base low, Build rising, Peak highest, Taper dropping sharply)" },
            key_workouts: { type: "array", items: { type: "string" }, description: "3-5 short example key workouts for this phase" },
          },
          required: ["name", "weeks", "focus", "weekly_volume_guidance", "weekly_time_estimate", "relative_load", "key_workouts"],
          additionalProperties: false,
        },
      },
      recovery_guidelines: { type: "array", items: { type: "string" }, description: "5-8 short, concrete recovery recommendations across the whole plan — sleep, mobility, deload timing, injury-prevention signals to watch for" },
      nutrition_plan: { type: "array", items: { type: "string" }, description: "5-8 short, concrete nutrition recommendations tailored to the event type and training volume — daily fueling, hydration, race-specific fueling practice, supplementation if relevant" },
      pre_race_prep: { type: "array", items: { type: "string" }, description: "5-8 short, concrete steps for the final 48-72 hours before the event (taper, carb-loading, logistics, sleep, gear check, course familiarization)" },
      race_day_strategy: { type: "array", items: { type: "string" }, description: "5-8 short, concrete race-day recommendations (pacing plan tied to the goal finish time if one was given, fueling/hydration timing, warmup, mental approach, contingency for tough patches)" },
    },
    required: ["overview", "phases", "recovery_guidelines", "nutrition_plan", "pre_race_prep", "race_day_strategy"],
    additionalProperties: false,
  },
  strict: true,
};

const TRAINING_PLAN_SYSTEM_PROMPT = `You are a sports-science coaching assistant embedded in a Strava analytics app \
called Splitline. You are given an aggregated statistical summary of one athlete's last 30 imported activities \
(never raw personal data) plus their upcoming event: type (running, duathlon, or triathlon), distance, a goal finish \
time band if they chose one (otherwise "just finish"), and exact weeks remaining until the event. Produce a \
detailed, grounded, progressive (periodized) training plan that spans the entire time remaining — group it into \
3-8 phases (e.g. Base, Build, Peak, Taper) rather than one entry per week, since the time remaining can range from \
a few weeks to many months. Base every recommendation on the athlete's actual recent training patterns (weekly \
volume, sport mix, intensity, rest frequency) given to you — do not invent data points, and say plainly when the \
athlete's current volume looks insufficient or excessive for the goal rather than ignoring it. When a goal finish \
time was given, use it to set concrete pacing targets in the race-day strategy and to calibrate how aggressive the \
build needs to be; when it wasn't, plan for a confident finish rather than a specific time. Each phase needs a \
relative_load value (0-100, phase to phase, peak week = 100) so the app can chart the training-load ramp — keep \
these numbers internally consistent with the weekly_volume_guidance and weekly_time_estimate you write for that \
phase. Recovery, nutrition, pre-race prep, and race-day strategy should each be genuinely detailed and specific to \
this athlete and event, not generic filler — reference actual numbers from the summary and the chosen distance \
wherever it sharpens the advice. Keep every individual bullet point concise (under 30 words) even though there are \
more of them. This is wellness/training guidance, not a certified coaching or medical service; do not claim \
otherwise.`;

function client() {
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) {
    throw new Error("ANTHROPIC_API_KEY is not set. See README.md for how to configure it.");
  }
  return new Anthropic({ apiKey });
}

async function callForTool({ system, tool, userContent, effort = "high", maxTokens = 4000 }) {
  const res = await client().messages.create({
    model: MODEL,
    max_tokens: maxTokens,
    // Each feature's system prompt + tool schema is a fixed string
    // literal shared by every user's call to that feature — only
    // `userContent` (the athlete's JSON payload) varies per request. That
    // makes this the textbook "shared prefix, varying suffix" case for
    // prompt caching: marking the last (only) system block caches tools +
    // system together (tools render first in the request), while the
    // per-request payload after it is never touched by the breakpoint.
    system: [{ type: "text", text: system, cache_control: { type: "ephemeral" } }],
    output_config: { effort },
    tools: [tool],
    tool_choice: { type: "tool", name: tool.name },
    messages: [{ role: "user", content: userContent }],
  });

  const u = res.usage;
  console.log(
    `[anthropic:cache] tool=${tool.name} cache_read=${u.cache_read_input_tokens} ` +
    `cache_write=${u.cache_creation_input_tokens} uncached=${u.input_tokens}`
  );

  if (res.stop_reason === "refusal") {
    throw new Error("The AI analysis was declined for this request.");
  }
  const toolUse = res.content.find((b) => b.type === "tool_use" && b.name === tool.name);
  if (!toolUse) throw new Error("The AI analysis didn't return a structured result.");
  return toolUse.input;
}

// `summary` is the plain-object stats bundle from lib/insights.js's
// buildActivitySummary — never the raw activity rows.
export async function generateHealthAnalysis(summary) {
  const result = await callForTool({
    system: SYSTEM_PROMPT,
    tool: ANALYSIS_TOOL,
    userContent: `Here is the athlete's activity summary (JSON):\n\n${JSON.stringify(summary, null, 2)}`,
  });
  result.risk_score = Math.max(0, Math.min(100, Math.round(Number(result.risk_score) || 0)));
  return result;
}

// `summary` is buildActivitySummary's output; `goal` is
// { eventType, eventName, eventDate, targetDistance, goalTime, weeksUntilEvent }.
export async function generateTrainingPlan(summary, goal) {
  const payload = { athlete_activity_summary: summary, upcoming_event: goal };
  const plan = await callForTool({
    system: TRAINING_PLAN_SYSTEM_PROMPT,
    tool: TRAINING_PLAN_TOOL,
    userContent: `Here is the athlete's data (JSON):\n\n${JSON.stringify(payload, null, 2)}`,
    // "medium" rather than "high" — this schema (phases + 4 detailed
    // bullet lists) is bigger than the health analysis, so the extra
    // thinking budget of "high" costs latency that matters on a
    // synchronous HTTP request. Quality holds up well at "medium" for
    // structured planning content; see README for the platform timeout
    // tradeoff this manages.
    effort: "medium",
    // More content per phase (weekly_time_estimate, relative_load) and
    // longer bullet lists (5-8 vs. 3-6) need more room than the default.
    maxTokens: 6000,
  });
  for (const phase of plan.phases || []) {
    phase.relative_load = Math.max(0, Math.min(100, Math.round(Number(phase.relative_load) || 0)));
  }
  return plan;
}

const DEVIATION_TOOL_NAME = "submit_training_plan_deviation";

const DEVIATION_TOOL = {
  name: DEVIATION_TOOL_NAME,
  description: "Submit the structured comparison of an athlete's actual training against their saved training plan.",
  input_schema: {
    type: "object",
    properties: {
      significant_deviation: { type: "boolean", description: "true if any category below deviates from what the plan implies by roughly 10% or more" },
      narrative: { type: "string", description: "2-4 sentence plain-language summary of how actual training compares to the plan so far" },
      categories: {
        type: "array",
        description: "0-5 entries — only include a category here when it deviates from the plan's implied targets by roughly 10% or more",
        items: {
          type: "object",
          properties: {
            category: { type: "string", enum: ["distance", "pace", "power", "heart_rate", "fatigue"] },
            direction: { type: "string", enum: ["under", "over"] },
            deviation_pct: { type: "integer", description: "Approximate magnitude of the deviation as a percent, e.g. 25 for a 25% shortfall or overshoot" },
            description: { type: "string", description: "1-2 sentences on what this deviation is and why it matters, referencing the actual numbers given" },
          },
          required: ["category", "direction", "deviation_pct", "description"],
          additionalProperties: false,
        },
      },
      weekly_review: {
        type: "array",
        description: "One entry per elapsed week since the plan started (the weekly_actuals_since_plan given to you), in order",
        items: {
          type: "object",
          properties: {
            week_number: { type: "integer" },
            phase_name: { type: "string", description: "Must exactly match the name of whichever given plan phase this week falls into" },
            status: { type: "string", enum: ["on_track", "missed", "exceeded", "insufficient_data"] },
            miss_pct: { type: "integer", description: "Approximate percent this week fell short (status=missed) or ran over (status=exceeded) the plan's implied target for that week; 0 for on_track or insufficient_data" },
            note: { type: "string", description: "1 short sentence specific to this week" },
          },
          required: ["week_number", "phase_name", "status", "miss_pct", "note"],
          additionalProperties: false,
        },
      },
      goal_impact_likelihood: { type: "string", enum: ["low", "moderate", "high"], description: "Likelihood that this deviation, if it continues, meaningfully affects the athlete reaching their event goal" },
      goal_impact_narrative: { type: "string", description: "1-3 sentences explaining that likelihood assessment, grounded in the specific deviation found" },
      recommended_action: {
        type: "string",
        enum: ["regenerate", "adjust", "continue"],
        description: "regenerate: the plan no longer fits current fitness/circumstances and should be rebuilt from scratch; adjust: the plan's overall shape is still right but upcoming phases should be tweaked; continue: the deviation is minor enough to keep following the plan as-is",
      },
    },
    required: ["significant_deviation", "narrative", "categories", "weekly_review", "goal_impact_likelihood", "goal_impact_narrative", "recommended_action"],
    additionalProperties: false,
  },
  strict: true,
};

const DEVIATION_SYSTEM_PROMPT = `You are the analysis engine behind the training-plan deviation check in a Strava \
analytics app called Splitline. An athlete has a saved progressive training plan (phases with a name, a week \
range like "Weeks 1-4", a focus, weekly volume guidance, a weekly time estimate, and a relative training-load \
value) and you are given their actual training data since that plan was generated: week-by-week actuals \
(distance, moving time, average pace, average heart rate, average power, session count, and an estimated \
training-load figure for each elapsed week, counted from the plan's own start), plus their broader rolling \
30-day context (weekly distance by calendar week, aerobic decoupling and cadence drift windows, and \
acute:chronic workload ratio as a fatigue signal). The plan's weekly_volume_guidance is deliberately a text \
range, not a rigid number — infer the implied numeric target for each elapsed week from that text (and from \
weekly_time_estimate and relative_load) and judge, week by week, whether the athlete's actual training tracked \
it, fell meaningfully short, or ran over. A deviation counts as significant once any of distance, pace, power, \
heart rate, or fatigue is off from what the plan implies by roughly 10% or more — ground every category and \
weekly note in the specific numbers you were given, never invent a number you weren't given. Heart-rate and \
fatigue deviations should be read together with the biomechanics/ACWR signals given (e.g. rising decoupling or \
an ACWR spike alongside a volume shortfall points to overtraining risk, not just an easy taper). A week with \
zero sessions and no data is real signal — call it "missed", not "insufficient_data"; use "insufficient_data" \
only when there genuinely isn't enough recorded to judge (e.g. a week that just started). Each phase_name you \
write in weekly_review must exactly match one of the given phase names. This is a judgment call an experienced \
coach would make from imperfect real-world data, not a precise formula — say so implicitly by keeping every \
percentage an approximation and never overstating certainty. This is wellness/training guidance, not a \
certified coaching or medical service; do not claim otherwise.`;

// `payload` is { plan_phases, plan_generated_at, weeks_since_plan_started,
// upcoming_event, weekly_actuals_since_plan, recent_30day_weekly_distance_km,
// biomechanics, training_load } — see app/api/training-plan/deviation/route.js.
export async function generateTrainingPlanDeviation(payload) {
  const result = await callForTool({
    system: DEVIATION_SYSTEM_PROMPT,
    tool: DEVIATION_TOOL,
    userContent: `Here is the athlete's plan and actual training data (JSON):\n\n${JSON.stringify(payload, null, 2)}`,
    effort: "medium",
    maxTokens: 4000,
  });
  result.categories = (result.categories || []).map((c) => ({ ...c, deviation_pct: Math.max(0, Math.round(Number(c.deviation_pct) || 0)) }));
  result.weekly_review = (result.weekly_review || []).map((w) => ({ ...w, miss_pct: Math.max(0, Math.round(Number(w.miss_pct) || 0)) }));
  return result;
}

const ADJUST_TRAINING_PLAN_SYSTEM_PROMPT = `You are a sports-science coaching assistant embedded in a Strava \
analytics app called Splitline, revising an athlete's existing progressive training plan mid-cycle rather than \
writing one from scratch. You are given the athlete's current activity summary, their upcoming event (with \
weeks remaining recalculated as of today), the existing plan you are revising, and a structured deviation \
analysis describing how their actual training since that plan was generated has diverged from it (by how much, \
in which categories, week by week, and an assessment of how much this threatens their event goal). Produce a \
complete revised plan in the same shape as the original: treat weeks that have already happened as fixed \
history you cannot undo, and focus the real changes on the phases and weeks still ahead — extend a phase, \
soften or raise upcoming volume, insert extra recovery, or shift the taper, whatever the deviation and the \
weeks remaining actually call for. Explain in the overview specifically what changed from the original plan and \
why, tied to the deviation given. Do not invent data points you weren't given. Each phase still needs a \
relative_load value (0-100, phase to phase, peak week = 100) consistent with its weekly_volume_guidance and \
weekly_time_estimate. This is wellness/training guidance, not a certified coaching or medical service; do not \
claim otherwise.`;

// `existingPlan` is the current cached plan payload; `deviation` is
// generateTrainingPlanDeviation's output (or null if unavailable) —
// output matches generateTrainingPlan's shape exactly, so it's cached
// and rendered identically.
export async function generateAdjustedTrainingPlan(summary, goal, existingPlan, deviation) {
  const payload = { athlete_activity_summary: summary, upcoming_event: goal, existing_plan: existingPlan, deviation_analysis: deviation };
  const plan = await callForTool({
    system: ADJUST_TRAINING_PLAN_SYSTEM_PROMPT,
    tool: TRAINING_PLAN_TOOL,
    userContent: `Here is the athlete's data (JSON):\n\n${JSON.stringify(payload, null, 2)}`,
    effort: "medium",
    maxTokens: 6000,
  });
  for (const phase of plan.phases || []) {
    phase.relative_load = Math.max(0, Math.min(100, Math.round(Number(phase.relative_load) || 0)));
  }
  return plan;
}

